        _hole2.addCurve(to: CGPoint(x: 0.565625*width, y: 0.640625*height), control1: CGPoint(x: 0.528125*width, y: 0.6238356781*height), control2: CGPoint(x: 0.5449143219*width, y: 0.640625*height))
        path.addReversedPath(_hole2)
        return path
    }
